<template><section class="defaults-page"><div class="page-heading"><div><h1 class="page-title">账户默认创意组件</h1><p>按账户配置多账户批量创意所需组件；每次创建前仍会向腾讯重新验证。</p></div></div><el-alert type="info" :closable="false" title="解析优先级：账户+规格 → 账户+创意类型 → 账户+推广目标 → 账户通用默认。不会随机选取组件。" /><div class="panel"><div class="toolbar"><el-select v-model="accountId" filterable placeholder="选择腾讯账户" @change="accountChanged"><el-option v-for="item in options?.accounts || []" :key="item.id" :value="item.id" :label="`${item.name} · ${item.accountNo}`" /></el-select><el-button v-if="canManage" type="primary" :disabled="!accountId" @click="dialogOpen=true;loadAssets()">新增默认组件</el-button></div><div class="table-scroll"><el-table :data="rows" stripe><el-table-column prop="componentType" label="组件字段" min-width="150" /><el-table-column prop="componentName" label="组件名称" min-width="220" /><el-table-column prop="platformComponentId" label="腾讯组件 ID" min-width="150" /><el-table-column prop="templateId" label="适用规格" min-width="130"><template #default="{row}">{{row.templateId||'通用'}}</template></el-table-column><el-table-column prop="creativeType" label="创意类型" min-width="150"><template #default="{row}">{{row.creativeType||'通用'}}</template></el-table-column><el-table-column prop="status" label="状态" width="100" /><el-table-column v-if="canManage" label="操作" width="100"><template #default="{row}"><el-button link type="danger" @click="disable(row.id)">停用</el-button></template></el-table-column></el-table></div></div><el-dialog v-model="dialogOpen" title="新增账户默认组件" width="min(720px,94vw)"><el-form label-position="top"><el-form-item label="组件类别"><el-select v-model="assetType" @change="loadAssets"><el-option v-for="item in componentTypes" :key="item.value" :value="item.value" :label="item.label" /></el-select></el-form-item><el-form-item label="腾讯组件" required><el-select v-model="selectedId" filterable><el-option v-for="item in assets.filter(a=>a.platformAssetKind==='COMPONENT'&&a.usable)" :key="item.id" :value="item.id" :label="`${componentDisplayName(item)} · ${item.platformAssetId}`" /></el-select></el-form-item><el-form-item label="适用创意类型"><el-select v-model="creativeType" clearable><el-option label="普通创意" value="DYNAMIC_CREATIVE_TYPE_COMMON" /><el-option label="动态创意" value="DYNAMIC_CREATIVE_TYPE_PROGRAM" /></el-select></el-form-item><el-form-item label="适用规格 ID（留空为通用）"><el-input v-model="templateId" /></el-form-item><el-form-item label="优先级"><el-input-number v-model="priority" :min="0" :max="1000" /></el-form-item></el-form><template #footer><el-button @click="dialogOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存并验证</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{disableCreativeDefaultComponent,getCreativeDefaultComponents,getMultiAccountCreativeAssets,getMultiAccountCreativeOptions,saveCreativeDefaultComponent,type PromotionCreativeAsset,type PromotionCreativeBatchOptions}from'../api/admin';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),canManage=computed(()=>auth.hasPermission('PROMOTION_CREATIVE_DEFAULT_COMPONENT_MANAGE'));const options=ref<PromotionCreativeBatchOptions|null>(null),accountId=ref(''),rows=ref<any[]>([]),dialogOpen=ref(false),assets=ref<PromotionCreativeAsset[]>([]),assetType=ref('LANDING_PAGE'),selectedId=ref(''),creativeType=ref(''),templateId=ref(''),priority=ref(0),saving=ref(false);const componentTypes=[{label:'落地页',value:'LANDING_PAGE'},{label:'转化组件',value:'CONVERSION'},{label:'品牌形象',value:'BRAND'},{label:'视频号授权',value:'WECHAT_CHANNELS'},{label:'行动按钮',value:'ACTION_BUTTON'},{label:'文字链',value:'TEXT_LINK'},{label:'浮层卡片',value:'FLOATING_ZONE'},{label:'标签',value:'LABEL'},{label:'首评回复',value:'SOCIAL_SKILL'},{label:'其他组件',value:'OTHER'}];const componentDisplayName=(item:PromotionCreativeAsset)=>item.type==='BRAND'?item.name:item.contentSummary||item.name;async function init(){options.value=await getMultiAccountCreativeOptions();accountId.value=options.value.accounts[0]?.id||'';if(accountId.value)await accountChanged();}async function accountChanged(){rows.value=await getCreativeDefaultComponents(accountId.value);selectedId.value='';}async function loadAssets(){if(!accountId.value)return;const result=await getMultiAccountCreativeAssets({accountId:accountId.value,source:'ACCOUNT',assetType:assetType.value,page:1,pageSize:100,refresh:true});assets.value=result.list;selectedId.value='';}async function save(){const asset=assets.value.find(i=>i.id===selectedId.value);if(!asset)return ElMessage.warning('请选择腾讯组件');if(!asset.componentField)return ElMessage.warning('腾讯返回的该组件缺少组件字段，不能设为默认值');saving.value=true;try{await saveCreativeDefaultComponent({accountId:accountId.value,componentType:asset.componentField,platformComponentId:asset.platformAssetId,componentName:componentDisplayName(asset),creativeType:creativeType.value||undefined,templateId:templateId.value||undefined,priority:priority.value});ElMessage.success('默认组件已保存并通过腾讯账户可用性验证');dialogOpen.value=false;await accountChanged();}finally{saving.value=false;}}async function disable(id:string){await ElMessageBox.confirm('停用后新任务不再使用此默认组件。','确认停用',{type:'warning'});await disableCreativeDefaultComponent(id);await accountChanged();}onMounted(init);</script>
<style scoped>.defaults-page{display:grid;gap:16px}.page-title{margin:0 0 6px}.page-heading p{margin:0;color:var(--admin-text-muted)}.panel{padding:18px;border:1px solid var(--admin-border);border-radius:14px;background:#fff}.toolbar{display:flex;gap:10px;margin-bottom:15px}.toolbar :deep(.el-select){width:min(420px,100%)}.table-scroll{overflow-x:auto}.table-scroll :deep(.el-table){min-width:820px}@media(max-width:600px){.toolbar{flex-direction:column}.toolbar :deep(.el-select),.toolbar :deep(.el-button){width:100%;margin:0}}</style>
